def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter, deque

    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    seen = set()
    comps = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != bg and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            comps.append(comp)

    if not comps:
        return [row[:] for row in grid]

    source = max(comps, key=len)
    r0 = min(r for r, c in source)
    r1 = max(r for r, c in source)
    c0 = min(c for r, c in source)
    c1 = max(c for r, c in source)
    ar, ac = (r0 + r1) // 2, (c0 + c1) // 2
    template = [[grid[r][c] for c in range(c0, c1 + 1)] for r in range(r0, r1 + 1)]

    out = [row[:] for row in grid]
    source_set = set(source)
    for comp in comps:
        if comp is source or set(comp) == source_set:
            continue
        tr, tc = comp[0]
        for i in range(len(template)):
            for j in range(len(template[0])):
                y = tr + (r0 + i - ar)
                x = tc + (c0 + j - ac)
                if 0 <= y < h and 0 <= x < w:
                    out[y][x] = template[i][j]
    return out
